/* =====================================================================
   DATA HUNT — host backend, 3-LEVEL EDITION (Cloudflare Worker + D1)

   What it does
     • /host                 the organiser console (level clocks, checkpoint, board)
     • GET  /?mode=config    the game asks: which level is open, when does it end,
                             and (with &team=KEY) has THIS team qualified?
     • POST /                the game sends live heartbeats and per-level results
     • /api/host/*           console actions (needs your HOST_PIN)

   Setup (once): bind a D1 database as  DB  and add a secret  HOST_PIN.
   Tables are created automatically on first request (new *_3l tables —
   the old 10-island tables are left untouched).
   ===================================================================== */

const HOST_PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>DATA HUNT Host Console</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@700;900&family=JetBrains+Mono:wght@500;700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#08070B; --panel:#14111B; --panel2:#1B1724; --line:#2C2538; --line2:#3B3249;\n  --text:#F1ECF4; --mist:#A99FB4; --dim:#6F6680;\n  --gold:#FFD24A; --goldGlow:rgba(255,210,74,.28);\n  --ok:#35D39A; --bad:#FF6B6B; --amber:#E8912B; --cyan:#7FE3F5;\n  --l1:#35D39A; --l2:#E8912B; --l3:#FF6B6B;\n  --display:'Cinzel',Georgia,serif; --body:'Inter',system-ui,'Segoe UI',sans-serif; --mono:'JetBrains Mono',ui-monospace,Consolas,monospace;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml,body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 var(--body)}\nbody{background:radial-gradient(1200px 500px at 50% -200px,rgba(255,210,74,.07),transparent 70%),var(--bg);min-height:100vh}\n.wrap{max-width:1280px;margin:0 auto;padding:22px 16px 60px}\nheader{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}\nh1{font:900 24px var(--display);letter-spacing:.06em;color:var(--gold);margin:0}\nh1 small{display:block;font:600 11px var(--body);letter-spacing:.18em;text-transform:uppercase;color:var(--mist);margin-top:2px}\n.pill{font:600 12px var(--body);color:var(--mist);border:1px solid var(--line2);border-radius:999px;padding:5px 11px;display:inline-flex;align-items:center;gap:7px}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--dim)}\n.dot.on{background:var(--ok);box-shadow:0 0 8px var(--ok)} .dot.off{background:var(--bad)}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px}\n.grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:16px}\n@media (max-width:900px){.grid{grid-template-columns:1fr}}\n.label{font:600 11px var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--mist)}\n.steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin:0 0 16px}\n.step{border:1px solid var(--line2);border-radius:12px;padding:10px 12px;background:var(--panel);min-width:0}\n.step .k{font:700 10px var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--dim)}\n.step .t{font:700 14px var(--body);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.step .m{font:500 12px var(--mono);color:var(--mist)}\n.step.now{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold) inset;background:rgba(255,210,74,.06)}\n.step.done{opacity:.6}\n.step.s1 .t{color:var(--l1)} .step.s2 .t{color:var(--l2)} .step.s3 .t{color:var(--l3)}\n@media (max-width:700px){.steps{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.clock{font:700 clamp(64px,12vw,120px)/1 var(--mono);letter-spacing:-.02em;margin:10px 0 6px;font-variant-numeric:tabular-nums}\n.clock.running{color:var(--gold);text-shadow:0 0 40px var(--goldGlow)}\n.clock.warn{color:var(--amber)} .clock.crit{color:var(--bad)} .clock.paused{color:var(--cyan)} .clock.idle,.clock.ended{color:var(--dim)}\n.phase{font:700 15px var(--body)}\n.sub{color:var(--mist);font-size:13px;margin-top:4px;min-height:20px}\n.controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px;align-items:center}\nbutton{font:700 14px var(--body);border-radius:10px;border:1px solid var(--line2);background:var(--panel2);color:var(--text);padding:11px 16px;cursor:pointer;transition:transform .08s,background .15s}\nbutton:hover:not(:disabled){background:#241f30} button:active:not(:disabled){transform:translateY(1px)}\nbutton:disabled{opacity:.35;cursor:not-allowed}\nbutton.gold{background:var(--gold);border-color:var(--gold);color:#1A1203} button.gold:hover:not(:disabled){background:#ffdc6e}\nbutton.danger{border-color:rgba(255,107,107,.5);color:var(--bad)} button.danger:hover:not(:disabled){background:rgba(255,107,107,.1)}\nbutton.small{padding:7px 11px;font-size:12px}\ninput,select{font:500 15px var(--body);background:#0C0A11;color:var(--text);border:1px solid var(--line2);border-radius:10px;padding:10px 12px}\ninput:focus,select:focus{outline:2px solid var(--gold);outline-offset:1px}\n.mins{display:flex;align-items:center;gap:8px}\n.mins input{width:90px;text-align:center;font:700 18px var(--mono)}\n.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n.tile{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:12px}\n.tile .v{font:700 30px/1.1 var(--mono);margin-top:4px;font-variant-numeric:tabular-nums}\n.tile.ok .v{color:var(--ok)} .tile.bad .v{color:var(--bad)} .tile.amber .v{color:var(--amber)} .tile.gold .v{color:var(--gold)} .tile.cyan .v{color:var(--cyan)}\n.qual{margin-top:16px;border-color:rgba(255,210,74,.45);box-shadow:0 0 0 1px rgba(255,210,74,.12),0 20px 60px -30px var(--goldGlow)}\n.qual h2,.final h2{font:900 22px var(--display);color:var(--gold);margin:0 0 4px;letter-spacing:.05em}\n.qrow{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:12px}\n.qrow input{width:80px;text-align:center;font:700 16px var(--mono)}\n.res-tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:14px}\n@media (max-width:700px){.res-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.final{margin-top:16px;border-color:rgba(255,210,74,.45)}\n.podium{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}\n.podium .tile .v{font-size:20px;font-family:var(--body)}\n.toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;margin:22px 0 10px}\n.toolbar h3{margin:0;font:700 16px var(--body)}\n.toggle{display:inline-flex;align-items:center;gap:7px;font:600 13px var(--body);color:var(--mist);cursor:pointer;user-select:none}\n.toggle input{width:auto;accent-color:var(--gold)}\n.tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:var(--panel)}\ntable{border-collapse:collapse;width:100%;font-size:13px;min-width:1100px}\nth,td{padding:9px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}\nth{font:600 11px var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--mist);background:var(--panel2);position:sticky;top:0;white-space:nowrap}\nth.l1{color:var(--l1)} th.l2{color:var(--l2)} th.l3{color:var(--l3)}\ntd.num{font-family:var(--mono);text-align:right;white-space:nowrap} th.num{text-align:right}\ntd.lv{font-family:var(--mono);white-space:nowrap;font-size:12px}\ntd.lv b{font-size:13px}\ntr:last-child td{border-bottom:0}\ntr.elim td{opacity:.45}\n.team{font-weight:700}\n.emails{color:var(--mist);font-size:12px;word-break:break-all}\n.badge{display:inline-block;font:700 11px var(--body);padding:3px 9px;border-radius:999px;white-space:nowrap;border:1px solid}\n.b-play{color:var(--cyan);border-color:rgba(127,227,245,.4)} .b-done{color:var(--ok);border-color:rgba(53,211,154,.45)}\n.b-time{color:var(--bad);border-color:rgba(255,107,107,.45)} .b-wait{color:var(--amber);border-color:rgba(232,145,43,.45)}\n.b-off{color:var(--dim);border-color:var(--line2)} .b-reg{color:var(--gold);border-color:rgba(255,210,74,.45)}\n.pass{color:var(--ok);font-weight:700} .fail{color:var(--bad);font-weight:700}\n.qchk{width:20px;height:20px;accent-color:var(--ok);cursor:pointer}\n.lock{color:var(--dim)}\n.empty{padding:34px;text-align:center;color:var(--mist)}\n.linkrow{display:flex;gap:8px;margin-top:8px} .linkrow input{flex:1;font:500 13px var(--mono);min-width:0}\n.out{font:500 12px var(--mono);color:var(--ok);word-break:break-all;margin-top:8px;min-height:18px}\n.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(20px);background:var(--panel2);border:1px solid var(--line2);padding:11px 18px;border-radius:12px;opacity:0;transition:.25s;pointer-events:none;font-weight:600;z-index:50;max-width:calc(100% - 32px)}\n.toast.show{opacity:1;transform:translateX(-50%)}\n.gate{max-width:380px;margin:12vh auto 0;text-align:center}\n.gate h1{font-size:30px;margin-bottom:8px}\n.gate p{color:var(--mist);margin:0 0 18px}\n.gate input{width:100%}\n.gate .err{color:var(--bad);min-height:22px;margin-top:10px;font-size:14px}\n.flash{animation:flash 1s ease 3}\n@keyframes flash{50%{background:rgba(255,210,74,.12)}}\n</style>\n</head>\n<body>\n\n<div class=\"wrap\" id=\"gate\">\n  <div class=\"gate card\">\n    <h1>DATA HUNT</h1>\n    <p>Host console. Enter the host PIN you set in Cloudflare.</p>\n    <input type=\"password\" id=\"pinInput\" placeholder=\"Host PIN\" autocomplete=\"current-password\" style=\"text-align:center;font:700 20px var(--mono);letter-spacing:.2em\">\n    <div style=\"margin-top:12px\"><button class=\"gold\" id=\"pinBtn\" style=\"width:100%\">Open console</button></div>\n    <div class=\"err\" id=\"pinErr\"></div>\n  </div>\n</div>\n\n<div class=\"wrap\" id=\"app\" hidden>\n  <header>\n    <h1>DATA HUNT<small>Host console \u00b7 3 levels \u00b7 Round <span id=\"roundNo\">1</span></small></h1>\n    <div style=\"display:flex;gap:8px;flex-wrap:wrap\">\n      <span class=\"pill\"><span class=\"dot\" id=\"connDot\"></span><span id=\"connText\">Connecting\u2026</span></span>\n      <button class=\"small\" id=\"lockBtn\">Lock console</button>\n    </div>\n  </header>\n\n  <div class=\"steps\" id=\"steps\"></div>\n\n  <div class=\"grid\">\n    <section class=\"card\">\n      <div class=\"label\" id=\"clockLabel\">Event clock</div>\n      <div class=\"clock idle\" id=\"clock\">--:--</div>\n      <div class=\"phase\" id=\"phase\">Not started</div>\n      <div class=\"sub\" id=\"phaseSub\"></div>\n      <div class=\"controls\" id=\"ctlStart\">\n        <div class=\"mins\"><input type=\"number\" id=\"minsInput\" min=\"1\" max=\"600\" value=\"25\" aria-label=\"Minutes\"><span class=\"label\">min</span></div>\n        <button class=\"gold\" id=\"startBtn\">\u25b6 Start Level 1</button>\n      </div>\n      <div class=\"controls\" id=\"ctlRun\" hidden>\n        <button id=\"pauseBtn\">\u23f8 Pause</button>\n        <button id=\"resumeBtn\" class=\"gold\" hidden>\u25b6 Resume</button>\n        <button class=\"small\" data-add=\"-1\">\u22121 min</button>\n        <button class=\"small\" data-add=\"1\">+1 min</button>\n        <button class=\"small\" data-add=\"5\">+5 min</button>\n        <button class=\"danger\" id=\"endBtn\">\u25a0 End level now</button>\n      </div>\n      <div class=\"controls\">\n        <button class=\"small danger\" id=\"resetBtn\">\u21ba New round (clears the board)</button>\n      </div>\n    </section>\n\n    <section class=\"card\">\n      <div class=\"label\">Teams</div>\n      <div class=\"tiles\" style=\"margin-top:10px\">\n        <div class=\"tile gold\"><div class=\"label\">Registered</div><div class=\"v\" id=\"tTeams\">0</div></div>\n        <div class=\"tile\"><div class=\"label\">Players</div><div class=\"v\" id=\"tPlayers\">0</div></div>\n        <div class=\"tile cyan\"><div class=\"label\">Playing now</div><div class=\"v\" id=\"tPlaying\">0</div></div>\n        <div class=\"tile amber\"><div class=\"label\">Done \u00b7 waiting</div><div class=\"v\" id=\"tWaiting\">0</div></div>\n        <div class=\"tile ok\"><div class=\"label\">Still in</div><div class=\"v\" id=\"tIn\">0</div></div>\n        <div class=\"tile bad\"><div class=\"label\">Eliminated</div><div class=\"v\" id=\"tOut\">0</div></div>\n      </div>\n      <div style=\"margin-top:14px\">\n        <div class=\"label\">Player link</div>\n        <div class=\"linkrow\"><input id=\"gameUrl\" placeholder=\"https://data-hunt-csda.pages.dev/\"><button class=\"small\" id=\"copyLink\">Copy</button></div>\n        <div class=\"out\" id=\"linkOut\"></div>\n      </div>\n    </section>\n  </div>\n\n  <!-- checkpoint: who passed level L and moves to L+1 -->\n  <section class=\"card qual\" id=\"qual\" hidden>\n    <h2 id=\"qTitle\">Checkpoint \u2014 Level 1 results</h2>\n    <div class=\"sub\" id=\"qSub\"></div>\n    <div class=\"res-tiles\">\n      <div class=\"tile ok\"><div class=\"label\">Passed</div><div class=\"v\" id=\"qPass\">0</div></div>\n      <div class=\"tile bad\"><div class=\"label\">Did not pass</div><div class=\"v\" id=\"qFail\">0</div></div>\n      <div class=\"tile amber\"><div class=\"label\">No result sent</div><div class=\"v\" id=\"qPend\">0</div></div>\n      <div class=\"tile gold\"><div class=\"label\">Level leader</div><div class=\"v\" id=\"qTop\" style=\"font-size:18px;font-family:var(--body)\">\u2014</div></div>\n    </div>\n    <div class=\"qrow\">\n      <span class=\"label\">Qualify rule</span>\n      <select id=\"qRule\">\n        <option value=\"min\">Solved at least \u2026 of 5 in this level</option>\n        <option value=\"top\">Top \u2026 teams by this level's score</option>\n        <option value=\"toptotal\">Top \u2026 teams by total score</option>\n      </select>\n      <input type=\"number\" id=\"qVal\" min=\"0\" max=\"999\" value=\"3\">\n      <button class=\"small\" id=\"qResetOverrides\">Clear manual ticks</button>\n      <span class=\"sub\" style=\"margin:0\">Tick / untick a team in the table to override.</span>\n    </div>\n  </section>\n\n  <section class=\"card final\" id=\"final\" hidden>\n    <h2>\ud83c\udfc6 Final standings</h2>\n    <div class=\"sub\" id=\"fSub\"></div>\n    <div class=\"podium\" id=\"podium\"></div>\n  </section>\n\n  <div class=\"toolbar\">\n    <h3 id=\"tableTitle\">Teams</h3>\n    <div style=\"display:flex;gap:14px;flex-wrap:wrap;align-items:center\">\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"revealChk\"> Show live scores</label>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"voiceChk\" checked> Speak aloud</label>\n      <button class=\"small\" id=\"testVoice\">\ud83d\udd0a Test voice</button>\n      <button class=\"small gold\" id=\"csvBtn\">\u2b07 Download Excel (CSV)</button>\n    </div>\n  </div>\n  <div class=\"tablewrap\">\n    <table>\n      <thead><tr>\n        <th>#</th><th>Team</th><th>Members \u00b7 Email IDs</th><th>Sets</th><th>Status</th>\n        <th class=\"l1\">L1 Easy</th><th class=\"l2\">L2 Medium</th><th class=\"l3\">L3 Hard</th>\n        <th class=\"num\">Total</th><th id=\"qHead\">Qualify</th><th class=\"num\">Seen</th><th></th>\n      </tr></thead>\n      <tbody id=\"tbody\"></tbody>\n    </table>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst API = location.origin;\nconst PLAN = {1:25, 2:40, 3:55};\nconst TAG = {1:'Easy', 2:'Medium', 3:'Hard'};\nconst LS = { get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }, set(k,v){ try{ localStorage.setItem(k,v); }catch(e){} }, del(k){ try{ localStorage.removeItem(k); }catch(e){} } };\nlet PIN = LS.get('dh_host_pin') || '';\nlet cfg = null, teams = [], levels = [], skew = 0, round = 1, lastOk = 0;\nlet passCount = null, prevKey = null, announceTimer = null, allDoneSpoken = false, busy = false;\nlet overrides = {};\n\nconst esc = s => String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst fmt = sec => { sec = Math.max(0, Math.floor(sec)); const h = Math.floor(sec/3600), m = Math.floor(sec%3600/60), s = sec%60; return (h ? h + ':' + String(m).padStart(2,'0') : String(m).padStart(2,'0')) + ':' + String(s).padStart(2,'0'); };\nconst now = () => Date.now() + skew;\nfunction toast(msg){ const t = $('toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(toast.t); toast.t = setTimeout(() => t.classList.remove('show'), 2800); }\n\nasync function api(path, body){\n  const res = await fetch(API + path, { method: body ? 'POST' : 'GET', headers: { 'X-Host-Pin': PIN, 'Content-Type': 'application/json' }, body: body ? JSON.stringify(body) : undefined, cache: 'no-store' });\n  const data = await res.json().catch(() => ({ ok:false, error:'Bad response ('+res.status+')' }));\n  if (res.status === 401) { lockConsole(data.error); throw new Error(data.error); }\n  return data;\n}\n\n/* ---------- PIN gate ---------- */\nasync function tryPin(p){\n  PIN = p; $('pinErr').textContent = '';\n  try{\n    const d = await api('/api/host/board');\n    if (!d.ok) { $('pinErr').textContent = d.error || 'Could not open.'; return; }\n    LS.set('dh_host_pin', PIN); $('gate').hidden = true; $('app').hidden = false; applyBoard(d); startLoops();\n  }catch(e){ if (!$('pinErr').textContent) $('pinErr').textContent = 'Could not reach the server.'; }\n}\nfunction lockConsole(msg){ LS.del('dh_host_pin'); PIN = ''; $('app').hidden = true; $('gate').hidden = false; $('pinErr').textContent = msg || ''; $('pinInput').value=''; $('pinInput').focus(); }\n$('pinBtn').onclick = () => tryPin($('pinInput').value.trim());\n$('pinInput').addEventListener('keydown', e => { if (e.key === 'Enter') tryPin($('pinInput').value.trim()); });\n$('lockBtn').onclick = () => lockConsole('');\n\n/* ---------- phase ---------- */\nfunction phaseOf(c){\n  if (!c || !c.level) return 'idle';\n  if (c.paused) return 'paused';\n  if (c.endAt && new Date(c.endAt).getTime() > now()) return 'running';\n  return 'ended';\n}\nfunction secondsLeft(c){\n  if (!c) return 0;\n  if (c.paused) return c.pausedLeft || 0;\n  if (!c.endAt) return 0;\n  return Math.max(0, Math.round((new Date(c.endAt).getTime() - now()) / 1000));\n}\nconst LVL = () => (cfg && cfg.level) | 0;\nconst nextLevel = () => phaseOf(cfg) === 'idle' ? 1 : (phaseOf(cfg) === 'ended' && LVL() < 3 ? LVL() + 1 : null);\n\n/* ---------- per-team view model ---------- */\nconst playersOf = t => String(t.members || '').split(',').map(s => s.trim()).filter(Boolean);\nfunction lvRow(t, n){ return levels.find(r => r.team_key === t.team_key && r.level === n) || null; }\nfunction model(){\n  const L = LVL(), ph = phaseOf(cfg);\n  return teams.map(t => {\n    const r = {1:lvRow(t,1), 2:lvRow(t,2), 3:lvRow(t,3)};\n    const allowed = t.allowed_level | 0;\n    const sumScore = [1,2,3].reduce((s,n) => s + (r[n] ? r[n].score|0 : 0), 0);\n    const sumTime = [1,2,3].reduce((s,n) => s + (r[n] ? r[n].time_sec|0 : 0), 0);\n    const sumSolved = [1,2,3].reduce((s,n) => s + (r[n] ? r[n].solved|0 : 0), 0);\n    const live = t.status === 'playing' && (t.cur_level|0) === L && !r[L];\n    const total = live ? Math.max(sumScore, t.score|0) : sumScore;\n    let st;\n    const stale = now() - (t.last_seen || 0) > 60000;\n    if (L >= 1 && allowed < L) st = { k:'out', label:'Eliminated after L' + (allowed), cls:'b-off' };\n    else if (L === 0 || (t.status === 'registered' && !r[1])) {\n      if (L >= 1 && ph === 'ended') st = { k:'nostart', label:'Registered \u00b7 never played', cls:'b-off' };\n      else st = { k:'reg', label: stale ? 'Registered \u00b7 offline?' : 'Registered \u00b7 waiting', cls: stale ? 'b-off' : 'b-reg' };\n    }\n    else if (r[L]) {\n      if (L === 3) st = { k:'done', label:'Finished all levels', cls:'b-done' };\n      else st = { k:'wait', label: (r[L].outcome || '').startsWith('Time') ? 'Time up \u00b7 waiting' : 'Done L' + L + ' \u00b7 waiting', cls:'b-wait' };\n    }\n    else if (ph === 'ended') st = { k:'nores', label:'No result from L' + L, cls:'b-time' };\n    else st = { k:'play', label: stale ? 'Playing \u00b7 offline?' : 'Playing L' + L, cls: stale ? 'b-off' : 'b-play' };\n    return Object.assign({}, t, { r, allowed, total, sumTime, sumSolved, st, liveSolved: live ? t.solved|0 : null });\n  });\n}\n/* who passes level L under the chosen rule (+ manual ticks) */\nfunction qualifiers(rows, L){\n  const rule = $('qRule').value, v = Math.max(0, parseInt($('qVal').value, 10) || 0);\n  const pool = rows.filter(t => t.allowed >= L && (t.r[L] || (t.cur_level|0) === L));\n  const solvedOf = t => t.r[L] ? t.r[L].solved|0 : 0;\n  const scoreOf = t => t.r[L] ? t.r[L].score|0 : 0;\n  const timeOf = t => t.r[L] ? t.r[L].time_sec|0 : 1e9;\n  let pass = new Set();\n  if (rule === 'min') pool.forEach(t => { if (solvedOf(t) >= v) pass.add(t.team_key); });\n  else {\n    const key = rule === 'top' ? (a, b) => scoreOf(b) - scoreOf(a) || timeOf(a) - timeOf(b) : (a, b) => b.total - a.total || a.sumTime - b.sumTime;\n    pool.slice().sort(key).slice(0, v).forEach(t => pass.add(t.team_key));\n  }\n  rows.forEach(t => { const o = overrides[t.team_key]; if (o === true && t.allowed >= L) pass.add(t.team_key); if (o === false) pass.delete(t.team_key); });\n  return { pool, pass };\n}\n\n/* ---------- render ---------- */\nfunction applyBoard(d){\n  cfg = d.config; teams = d.teams || []; levels = d.levels || []; round = d.round;\n  skew = (cfg.serverNow || Date.now()) - Date.now();\n  lastOk = Date.now();\n  if (LS.get('dh_ovr_round') !== String(round) + ':' + LVL()) { overrides = {}; LS.set('dh_ovr_round', String(round) + ':' + LVL()); LS.set('dh_ovr', '{}'); }\n  else { try{ overrides = JSON.parse(LS.get('dh_ovr') || '{}'); }catch(e){ overrides = {}; } }\n  $('roundNo').textContent = round;\n  if (!applyBoard.init) { applyBoard.init = true; const nx = nextLevel(); if (nx) $('minsInput').value = PLAN[nx]; }\n  renderAll();\n}\nfunction renderSteps(){\n  const L = LVL(), ph = phaseOf(cfg);\n  const items = [\n    { k:'Step 1', t:'Registration', m:'~10 min', s:'', st: L === 0 ? 'now' : 'done' },\n    { k:'Step 2', t:'Level 1 \u00b7 Easy', m:PLAN[1] + ' min', s:'s1', st: L === 1 ? 'now' : L > 1 ? 'done' : '' },\n    { k:'Step 3', t:'Level 2 \u00b7 Medium', m:PLAN[2] + ' min', s:'s2', st: L === 2 ? 'now' : L > 2 ? 'done' : '' },\n    { k:'Step 4', t:'Level 3 \u00b7 Hard', m:PLAN[3] + ' min', s:'s3', st: L === 3 && ph !== 'ended' ? 'now' : L === 3 ? 'done' : '' },\n    { k:'Step 5', t:'Prize & results', m:'~10 min', s:'', st: L === 3 && ph === 'ended' ? 'now' : '' }\n  ];\n  $('steps').innerHTML = items.map(i => `<div class=\"step ${i.s} ${i.st}\"><div class=\"k\">${i.k}</div><div class=\"t\">${i.t}</div><div class=\"m\">${i.m}</div></div>`).join('');\n}\nfunction renderClock(){\n  const ph = phaseOf(cfg), L = LVL(), left = secondsLeft(cfg), clock = $('clock'), nx = nextLevel();\n  clock.textContent = (ph === 'idle' || (ph === 'ended' && nx)) ? fmt((+$('minsInput').value || PLAN[nx || 1]) * 60) : fmt(left);\n  clock.className = 'clock ' + (ph === 'running' ? (left <= 60 ? 'crit' : left <= 300 ? 'warn' : 'running') : ph);\n  $('clockLabel').textContent = nx ? 'Next: Level ' + nx + ' \u00b7 ' + TAG[nx] + ' \u2014 set the minutes, then start' : 'Level ' + L + ' \u00b7 ' + TAG[L] + ' \u2014 clock (every team follows it)';\n  const names = { idle:'\u23f3 Registration open \u2014 teams are joining', running:'\ud83d\udfe2 Level ' + L + ' (' + TAG[L] + ') is running', paused:'\u23f8 Level ' + L + ' paused \u2014 every team is frozen', ended: L === 3 ? '\ud83c\udfc1 Hunt over \u2014 final standings below' : '\ud83d\uded1 Level ' + L + ' over \u2014 checkpoint' };\n  $('phase').textContent = names[ph];\n  let sub = '';\n  if (ph === 'running' && cfg.endAt) sub = 'Every team stops at ' + new Date(new Date(cfg.endAt).getTime() - skew).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit', second:'2-digit' }) + '.';\n  if (ph === 'paused') sub = fmt(left) + ' will remain when you resume.';\n  if (ph === 'ended' && nx) sub = 'Check who qualifies below, then start Level ' + nx + '. Only ticked teams continue \u2014 the rest see a thank-you screen.';\n  if (ph === 'ended' && !nx) sub = 'Announce the winners. Download the Excel file for the record.';\n  if (ph === 'idle') { const w = teams.length; sub = w ? w + ' team' + (w === 1 ? '' : 's') + ' registered. Press Start \u2014 every registered game opens Level 1 by itself.' : 'Teams appear below as they register.'; }\n  $('phaseSub').textContent = sub;\n  $('ctlStart').hidden = !nx;\n  if (nx) $('startBtn').textContent = '\u25b6 Start Level ' + nx + ' \u00b7 ' + TAG[nx] + (nx > 1 && passCount != null ? ' with ' + passCount + ' team' + (passCount === 1 ? '' : 's') : '');\n  $('ctlRun').hidden = !(ph === 'running' || ph === 'paused');\n  $('pauseBtn').hidden = ph !== 'running'; $('resumeBtn').hidden = ph !== 'paused';\n  $('connDot').className = 'dot ' + (Date.now() - lastOk < 12000 ? 'on' : 'off');\n  $('connText').textContent = Date.now() - lastOk < 12000 ? 'Live' : 'Reconnecting\u2026';\n  const key = L + ':' + ph;\n  if (prevKey !== null && prevKey !== key) onPhaseChange(prevKey, key);\n  prevKey = key;\n}\nfunction lvCell(t, n, reveal){\n  const r = t.r[n];\n  if (r) return reveal ? `<b>${r.solved}/5</b> \u00b7 ${r.score}<br><span style=\"color:var(--mist)\">${esc(r.time_used || '')}${r.hints ? ' \u00b7 ' + r.hints + ' hint' + (r.hints > 1 ? 's' : '') : ''}</span>` : '<span class=\"lock\">\u2713 \ud83d\udd12</span>';\n  if (LVL() === n && t.liveSolved != null) return reveal ? `<span style=\"color:var(--cyan)\">${t.liveSolved}/5 live</span>` : '<span class=\"lock\">\u2026</span>';\n  if (LVL() >= n && t.allowed < n) return '<span style=\"color:var(--dim)\">\u2014</span>';\n  return '';\n}\nfunction renderAll(){\n  renderSteps(); renderClock();\n  const ph = phaseOf(cfg), L = LVL(), nx = nextLevel();\n  const rows = model();\n  const checkpoint = ph === 'ended' && L >= 1 && L < 3;\n  const q = checkpoint ? qualifiers(rows, L) : null;\n\n  $('tTeams').textContent = rows.length;\n  $('tPlayers').textContent = rows.reduce((n, t) => n + playersOf(t).length, 0);\n  $('tPlaying').textContent = rows.filter(t => t.st.k === 'play').length;\n  $('tWaiting').textContent = rows.filter(t => t.st.k === 'wait' || t.st.k === 'done').length;\n  $('tOut').textContent = rows.filter(t => t.st.k === 'out').length;\n  $('tIn').textContent = rows.filter(t => t.st.k !== 'out' && t.st.k !== 'nostart').length;\n\n  // checkpoint panel\n  $('qual').hidden = !checkpoint;\n  if (checkpoint) {\n    const pend = q.pool.filter(t => !t.r[L]).length;\n    $('qTitle').textContent = 'Checkpoint \u2014 Level ' + L + ' (' + TAG[L] + ') results';\n    $('qPass').textContent = q.pass.size; $('qFail').textContent = q.pool.length - [...q.pass].filter(k => q.pool.some(t => t.team_key === k)).length; $('qPend').textContent = pend;\n    const top = q.pool.filter(t => t.r[L]).sort((a, b) => (b.r[L].score|0) - (a.r[L].score|0) || (a.r[L].time_sec|0) - (b.r[L].time_sec|0))[0];\n    $('qTop').textContent = top ? top.team + ' \u00b7 ' + top.r[L].score : '\u2014';\n    $('qSub').innerHTML = esc(q.pool.length) + ' teams played Level ' + L + '. <b style=\"color:var(--ok)\">' + q.pass.size + ' will move on to Level ' + (L + 1) + '</b>' + (pend ? ' \u00b7 <span style=\"color:var(--amber)\">' + pend + ' sent no result (closed tab?) \u2014 tick them by hand if they should continue</span>' : '') + '.';\n    passCount = q.pass.size; renderClock();\n  }\n\n  // final panel\n  const final = L === 3 && ph === 'ended';\n  $('final').hidden = !final;\n  if (final) {\n    const f = rows.filter(t => t.r[3] || t.allowed >= 3).sort((a, b) => b.total - a.total || a.sumTime - b.sumTime);\n    const medals = ['\ud83e\udd47 Winner', '\ud83e\udd48 Runner-up', '\ud83e\udd49 Third'];\n    $('podium').innerHTML = f.slice(0, 3).map((t, i) => `<div class=\"tile gold\"><div class=\"label\">${medals[i]}</div><div class=\"v\">${esc(t.team)}</div><div class=\"sub\">${t.total} pts \u00b7 ${t.sumSolved}/15 solved \u00b7 ${fmt(t.sumTime)}</div></div>`).join('') || '<div class=\"sub\">No team finished Level 3.</div>';\n    $('fSub').textContent = f.length + ' finalists \u00b7 ranked by total score, ties broken by total time used.';\n  }\n\n  // table\n  const reveal = ph === 'ended' || $('revealChk').checked;\n  const sorted = rows.slice();\n  if (final || checkpoint) sorted.sort((a, b) => (b.st.k !== 'out') - (a.st.k !== 'out') || b.total - a.total || a.sumTime - b.sumTime);\n  $('tableTitle').textContent = final ? 'Final standings' : checkpoint ? 'Level ' + L + ' standings \u2014 tick who qualifies' : 'Teams (join order)';\n  $('qHead').textContent = checkpoint ? '\u2192 L' + (L + 1) + '?' : 'Qualified';\n  $('tbody').innerHTML = sorted.length ? sorted.map((t, i) => {\n    const ago = t.last_seen ? Math.max(0, Math.round((now() - t.last_seen) / 1000)) : null;\n    const ms = playersOf(t), es = String(t.emails || '').split(',').map(s => s.trim());\n    let qcell = '';\n    if (checkpoint) {\n      if (t.allowed >= L) qcell = `<label class=\"toggle\"><input type=\"checkbox\" class=\"qchk\" data-q=\"${esc(t.team_key)}\" ${q.pass.has(t.team_key) ? 'checked' : ''}>${overrides[t.team_key] !== undefined ? '<span style=\"font-size:11px;color:var(--amber)\">manual</span>' : ''}</label>`;\n      else qcell = '<span style=\"color:var(--dim)\">\u2014</span>';\n    } else if (L >= 2) qcell = t.allowed >= L ? '<span class=\"pass\">\u2713 L' + L + '</span>' : '<span class=\"fail\">\u2715</span>';\n    return '<tr class=\"' + (t.st.k === 'out' ? 'elim' : '') + '\">' +\n      '<td class=\"num\">' + (i + 1) + '</td>' +\n      '<td class=\"team\">' + esc(t.team) + '</td>' +\n      '<td>' + ms.map((m, j) => esc(m) + (es[j] ? '<div class=\"emails\">' + esc(es[j]) + '</div>' : '')).join('') + '</td>' +\n      '<td style=\"font-family:var(--mono)\">' + esc(t.sets || '') + '</td>' +\n      '<td><span class=\"badge ' + t.st.cls + '\">' + esc(t.st.label) + '</span></td>' +\n      '<td class=\"lv\">' + lvCell(t, 1, reveal) + '</td><td class=\"lv\">' + lvCell(t, 2, reveal) + '</td><td class=\"lv\">' + lvCell(t, 3, reveal) + '</td>' +\n      '<td class=\"num\" style=\"color:var(--gold);font-weight:700\">' + (reveal ? t.total : '<span class=\"lock\">\ud83d\udd12</span>') + '</td>' +\n      '<td>' + qcell + '</td>' +\n      '<td class=\"num\" style=\"color:var(--mist)\">' + (ago == null ? '\u2014' : ago < 60 ? ago + 's' : Math.round(ago / 60) + 'm') + '</td>' +\n      '<td><button class=\"small\" data-remove=\"' + esc(t.team_key) + '\" title=\"Remove this team (e.g. a test team)\">\u2715</button></td>' +\n    '</tr>';\n  }).join('') : '<tr><td colspan=\"12\" class=\"empty\">No teams yet. They appear here the moment they register in the game.</td></tr>';\n\n  // everybody done before the clock ran out\n  const playing = rows.filter(t => t.st.k === 'play').length, inLevel = rows.filter(t => t.allowed >= L && t.st.k !== 'nostart').length;\n  if (ph === 'running' && L && inLevel && playing === 0 && !allDoneSpoken) {\n    allDoneSpoken = true; say('All teams have finished level ' + L + '. You can end the level now.'); toast('\u2705 Every team has finished Level ' + L);\n  }\n  if (playing > 0) allDoneSpoken = false;\n}\n\n/* ---------- announcements ---------- */\nfunction onPhaseChange(from, to){\n  const [fl, fp] = from.split(':'), [tl, tp] = to.split(':');\n  if (tp === 'ended' && (fp === 'running' || fp === 'paused')) {\n    beep(); say('Time is up for level ' + tl + '!');\n    clearTimeout(announceTimer);\n    announceTimer = setTimeout(async () => {\n      await refresh();\n      const rows = model(), L = +tl;\n      if (L < 3) { const q = qualifiers(rows, L); say('Level ' + L + ' results. ' + q.pass.size + ' of ' + q.pool.length + ' teams passed and move on to level ' + (L + 1) + '.'); $('qual').classList.add('flash'); setTimeout(() => $('qual').classList.remove('flash'), 3200); }\n      else { const f = rows.filter(t => t.r[3]).sort((a, b) => b.total - a.total || a.sumTime - b.sumTime); if (f[0]) say('The hunt is over. The winner is ' + f[0].team + ' with ' + f[0].total + ' points.'); }\n    }, 12000);\n  }\n  if (tp === 'running' && fl !== tl) { say('Level ' + tl + ', ' + TAG[tl] + ', has started.'); $('minsInput').value = PLAN[Math.min(3, +tl + 1)]; }\n}\nfunction say(text){\n  if (!$('voiceChk').checked || !('speechSynthesis' in window)) return;\n  try{ speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(text); u.rate = 0.95; u.lang = 'en-IN'; speechSynthesis.speak(u); }catch(e){}\n}\nlet actx = null;\nfunction beep(){\n  try{\n    actx = actx || new (window.AudioContext || window.webkitAudioContext)();\n    [0, .28, .56].forEach((t, i) => { const o = actx.createOscillator(), g = actx.createGain(); o.type = 'square'; o.frequency.value = i === 2 ? 660 : 880; g.gain.setValueAtTime(.0001, actx.currentTime + t); g.gain.exponentialRampToValueAtTime(.18, actx.currentTime + t + .02); g.gain.exponentialRampToValueAtTime(.0001, actx.currentTime + t + .24); o.connect(g).connect(actx.destination); o.start(actx.currentTime + t); o.stop(actx.currentTime + t + .26); });\n  }catch(e){}\n}\n$('testVoice').onclick = () => { beep(); const v = $('voiceChk').checked; $('voiceChk').checked = true; say('Voice is working. Results are read out when each level ends.'); $('voiceChk').checked = v; };\n\n/* ---------- actions ---------- */\nasync function act(body, okMsg){\n  if (busy) return; busy = true;\n  try{\n    const d = await api('/api/host/action', body);\n    if (!d.ok) toast('\u26a0\ufe0f ' + (d.error || 'Failed')); else { if (okMsg) toast(okMsg); await refresh(); }\n  }catch(e){ toast('\u26a0\ufe0f Could not reach the server'); }\n  busy = false;\n}\n$('startBtn').onclick = () => {\n  const nx = nextLevel(); if (!nx) return;\n  const m = Math.max(1, Math.min(600, parseInt($('minsInput').value, 10) || PLAN[nx]));\n  let qualified = null, msg;\n  if (nx === 1) msg = 'Start Level 1 (Easy) now for ' + m + ' minutes?\\n\\n' + teams.length + ' registered team' + (teams.length === 1 ? '' : 's') + ' go straight into the game.';\n  else {\n    const q = qualifiers(model(), nx - 1); qualified = [...q.pass];\n    if (!qualified.length) { toast('\u26a0\ufe0f No team is ticked to qualify.'); return; }\n    msg = 'Start Level ' + nx + ' (' + TAG[nx] + ') for ' + m + ' minutes?\\n\\n' + qualified.length + ' team' + (qualified.length === 1 ? '' : 's') + ' move on. Every other team sees a thank-you screen. This cannot be undone.';\n  }\n  if (!confirm(msg)) return;\n  beep(); allDoneSpoken = false;\n  act({ action:'start', level:nx, minutes:m, qualified }, '\u25b6 Level ' + nx + ' started \u2014 ' + m + ' minutes');\n};\n$('pauseBtn').onclick = () => act({ action:'pause' }, '\u23f8 Paused for everyone');\n$('resumeBtn').onclick = () => act({ action:'resume' }, '\u25b6 Resumed');\ndocument.querySelectorAll('[data-add]').forEach(b => b.onclick = () => { const m = +b.dataset.add; act({ action:'add', minutes:m }, (m > 0 ? '+' : '') + m + ' min for everyone'); });\n$('endBtn').onclick = () => { if (confirm('End Level ' + LVL() + ' now? Every team still playing stops and its result is sent.')) act({ action:'end' }, '\u25a0 Level ended'); };\n$('resetBtn').onclick = () => {\n  if (!confirm('Start a NEW ROUND? The board starts empty and every player device goes back to registration. Download the Excel file first if you need this round.')) return;\n  allDoneSpoken = false; overrides = {}; act({ action:'reset' }, '\u21ba New round ready');\n};\n$('tbody').addEventListener('click', e => {\n  const b = e.target.closest('[data-remove]'); if (!b) return;\n  if (confirm('Remove this team from the board?')) act({ action:'remove', teamKey:b.dataset.remove }, 'Removed');\n});\n$('tbody').addEventListener('change', e => {\n  const c = e.target.closest('[data-q]'); if (!c) return;\n  overrides[c.dataset.q] = c.checked; LS.set('dh_ovr', JSON.stringify(overrides)); renderAll();\n});\n$('qRule').onchange = () => { $('qVal').value = $('qRule').value === 'min' ? 3 : 10; LS.set('dh_qrule', $('qRule').value); renderAll(); };\n$('qVal').oninput = renderAll;\n$('qResetOverrides').onclick = () => { overrides = {}; LS.set('dh_ovr', '{}'); renderAll(); };\n$('revealChk').onchange = renderAll;\n$('minsInput').oninput = renderClock;\n$('voiceChk').checked = LS.get('dh_voice') !== 'off';\n$('voiceChk').onchange = () => LS.set('dh_voice', $('voiceChk').checked ? 'on' : 'off');\n\n/* ---------- player link ---------- */\n$('gameUrl').value = LS.get('dh_game_url') || 'https://data-hunt-csda.pages.dev/';\nfunction buildLink(){\n  const g = $('gameUrl').value.trim(); LS.set('dh_game_url', g);\n  if (!g) { $('linkOut').textContent = 'Paste your game\u2019s web address.'; $('linkOut').style.color = 'var(--mist)'; return ''; }\n  $('linkOut').textContent = g; $('linkOut').style.color = 'var(--ok)'; return g;\n}\n$('gameUrl').oninput = buildLink;\n$('copyLink').onclick = () => { const l = buildLink(); if (!l) return; (navigator.clipboard ? navigator.clipboard.writeText(l) : Promise.reject()).then(() => toast('Player link copied'), () => toast('Select the link and copy it')); };\nbuildLink();\n\n/* ---------- Excel / CSV ---------- */\n$('csvBtn').onclick = () => {\n  const rows = model().sort((a, b) => b.total - a.total || a.sumTime - b.sumTime);\n  const head = ['Rank','Team','Members','Email IDs','Players','Dataset sets (L1 L2 L3)','Status','Reached level','Total score','Total solved (of 15)','Total time'];\n  [1,2,3].forEach(n => head.push('L'+n+' solved','L'+n+' score','L'+n+' time','L'+n+' hints','L'+n+' wrong','L'+n+' result','L'+n+' Q1-Q5 seconds'));\n  head.push('Joined at');\n  const dt = ms => ms ? new Date(ms).toLocaleString() : '';\n  const lines = [head].concat(rows.map((t, i) => {\n    const line = [i + 1, t.team, t.members, t.emails, playersOf(t).length, t.sets, t.st.label, t.allowed, t.total, t.sumSolved, fmt(t.sumTime)];\n    [1,2,3].forEach(n => { const r = t.r[n]; let secs = ''; if (r) { try{ secs = JSON.parse(r.secs || '[]').join(' | '); }catch(e){} }\n      line.push(r ? r.solved : '', r ? r.score : '', r ? r.time_used : '', r ? r.hints : '', r ? r.wrong : '', r ? r.outcome : '', secs); });\n    line.push(dt(t.first_seen));\n    return line;\n  }));\n  const csv = '\ufeff' + lines.map(r => r.map(v => { const s = String(v == null ? '' : v); return /[\",\\n]/.test(s) ? '\"' + s.replace(/\"/g, '\"\"') + '\"' : s; }).join(',')).join('\\r\\n');\n  const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type:'text/csv;charset=utf-8' }));\n  a.download = 'DATA HUNT results - round ' + round + '.csv'; document.body.appendChild(a); a.click(); a.remove();\n  toast('Downloaded \u2014 opens in Excel');\n};\n\n/* ---------- loops ---------- */\nasync function refresh(){ try{ const d = await api('/api/host/board'); if (d.ok) applyBoard(d); }catch(e){} }\nlet loopsOn = false;\nfunction startLoops(){ if (loopsOn) return; loopsOn = true; setInterval(refresh, 3000); setInterval(() => { if (cfg) renderClock(); }, 250); }\n(function(){ const r = LS.get('dh_qrule'); if (r) { $('qRule').value = r; $('qVal').value = r === 'min' ? 3 : 10; } })();\n\nif (PIN) tryPin(PIN); else $('pinInput').focus();\n</script>\n</body>\n</html>\n";

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type,X-Host-Pin',
  'Access-Control-Max-Age': '86400'
};
const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...CORS } });

let schemaReady = false;
async function ensureSchema(db) {
  if (schemaReady) return;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS event_3l (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      round INTEGER NOT NULL DEFAULT 1,
      level INTEGER NOT NULL DEFAULT 0,
      open INTEGER NOT NULL DEFAULT 0,
      start_at INTEGER, end_at INTEGER,
      run_minutes INTEGER NOT NULL DEFAULT 25,
      paused INTEGER NOT NULL DEFAULT 0,
      paused_left INTEGER NOT NULL DEFAULT 0,
      updated_at INTEGER)`),
    db.prepare(`INSERT OR IGNORE INTO event_3l (id) VALUES (1)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS teams_3l (
      round INTEGER NOT NULL,
      team_key TEXT NOT NULL,
      team TEXT, members TEXT, emails TEXT, sets TEXT,
      status TEXT, cur_level INTEGER DEFAULT 0,
      score INTEGER DEFAULT 0, solved INTEGER DEFAULT 0, attempted INTEGER DEFAULT 0, hints INTEGER DEFAULT 0,
      seconds_left INTEGER, allowed_level INTEGER NOT NULL DEFAULT 1,
      first_seen INTEGER, last_seen INTEGER,
      PRIMARY KEY (round, team_key))`),
    db.prepare(`CREATE TABLE IF NOT EXISTS levels_3l (
      round INTEGER NOT NULL,
      team_key TEXT NOT NULL,
      level INTEGER NOT NULL,
      set_code TEXT, score INTEGER, solved INTEGER, attempted INTEGER, hints INTEGER, wrong INTEGER,
      skipped INTEGER, unanswered INTEGER, time_sec INTEGER, time_used TEXT, outcome TEXT,
      secs TEXT, pastes INTEGER, finished_at INTEGER,
      PRIMARY KEY (round, team_key, level))`)
  ]);
  schemaReady = true;
}

const getEvent = db => db.prepare('SELECT * FROM event_3l WHERE id = 1').first();

function publicConfig(ev, now) {
  return {
    ok: true,
    open: !!ev.open,
    level: ev.level | 0,
    startAt: ev.start_at ? new Date(ev.start_at).toISOString() : null,
    endAt: ev.end_at ? new Date(ev.end_at).toISOString() : null,
    runMinutes: ev.run_minutes,
    paused: !!ev.paused,
    pausedLeft: Math.round((ev.paused_left || 0) / 1000),
    round: ev.round,
    serverNow: now
  };
}

const str = (v, n = 200) => (v == null ? '' : String(v)).slice(0, n);
const int = v => { const n = Number(v); return Number.isFinite(n) ? Math.round(n) : 0; };
const keyOf = d => str(d.teamKey || ((d.team || '') + '|' + (d.emails || d.email || '')), 300).toLowerCase();

async function upsertLive(db, ev, key, d, status, now) {
  await db.prepare(`INSERT INTO teams_3l
      (round, team_key, team, members, emails, sets, status, cur_level, score, solved, attempted, hints, seconds_left, first_seen, last_seen)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT (round, team_key) DO UPDATE SET
      team=excluded.team, members=excluded.members, emails=excluded.emails, sets=excluded.sets,
      status=excluded.status, cur_level=excluded.cur_level, score=excluded.score, solved=excluded.solved,
      attempted=excluded.attempted, hints=excluded.hints, seconds_left=excluded.seconds_left, last_seen=excluded.last_seen`)
    .bind(ev.round, key, str(d.team, 60), str(d.members, 300), str(d.emails || d.email, 400), str(d.sets, 8),
      status, int(d.level), int(d.score != null ? d.score : d.total), int(d.solved), int(d.attempted), int(d.hints), int(d.secondsLeft), now, now)
    .run();
}

async function handlePlayerPost(db, d, now) {
  const ev = await getEvent(db);
  const key = keyOf(d);
  if (!key || key === '|') return json({ ok: false, error: 'missing team' }, 400);

  if (d.kind === 'leave') {
    await db.prepare("DELETE FROM teams_3l WHERE round=? AND team_key=? AND status='registered'").bind(ev.round, key).run();
    return json({ ok: true });
  }

  if (d.kind === 'live') {
    const ok = ['registered', 'playing', 'waiting', 'out', 'done'];
    await upsertLive(db, ev, key, d, ok.includes(d.status) ? d.status : 'playing', now);
    return json({ ok: true });
  }

  if (d.kind === 'level') {
    const lvl = Math.max(1, Math.min(3, int(d.level)));
    await db.prepare(`INSERT INTO levels_3l
        (round, team_key, level, set_code, score, solved, attempted, hints, wrong, skipped, unanswered, time_sec, time_used, outcome, secs, pastes, finished_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON CONFLICT (round, team_key, level) DO UPDATE SET
        set_code=excluded.set_code, score=excluded.score, solved=excluded.solved, attempted=excluded.attempted, hints=excluded.hints,
        wrong=excluded.wrong, skipped=excluded.skipped, unanswered=excluded.unanswered, time_sec=excluded.time_sec,
        time_used=excluded.time_used, outcome=excluded.outcome, secs=excluded.secs, pastes=excluded.pastes, finished_at=excluded.finished_at`)
      .bind(ev.round, key, lvl, str(d.set, 2), Math.max(0, int(d.score)), int(d.solved), int(d.attempted), int(d.hints), int(d.wrong),
        int(d.skipped), int(d.unanswered), int(d.timeSec), str(d.time, 12), str(d.outcome, 60),
        JSON.stringify(Array.isArray(d.secs) ? d.secs.slice(0, 5) : []), int(d.pastes), now)
      .run();
    await upsertLive(db, ev, key, Object.assign({}, d, { score: d.total, secondsLeft: 0 }), lvl === 3 ? 'done' : 'waiting', now);
    return json({ ok: true });
  }
  return json({ ok: false, error: 'unknown kind' }, 400);
}

async function handleHostAction(db, body, now) {
  const ev = await getEvent(db);
  let s = null;
  const running = ev.open && (ev.paused || (ev.end_at && ev.end_at > now));
  switch (body.action) {
    case 'start': {
      const lvl = int(body.level);
      if (lvl < 1 || lvl > 3) return json({ ok: false, error: 'Level must be 1, 2 or 3.' });
      if (running) return json({ ok: false, error: 'Level ' + ev.level + ' is still running. End it first.' });
      if (lvl !== (ev.level | 0) + 1) return json({ ok: false, error: 'The next level to start is Level ' + ((ev.level | 0) + 1) + '.' });
      const mins = Math.max(1, Math.min(600, int(body.minutes) || 25));
      const stmts = [];
      if (lvl >= 2) {
        const q = Array.isArray(body.qualified) ? body.qualified.map(k => str(k, 300)).filter(Boolean) : [];
        if (!q.length) return json({ ok: false, error: 'No team is marked as qualified.' });
        for (const k of q) stmts.push(db.prepare('UPDATE teams_3l SET allowed_level=? WHERE round=? AND team_key=? AND allowed_level>=?').bind(lvl, ev.round, k, lvl - 1));
      }
      stmts.push(db.prepare('UPDATE event_3l SET level=?, open=1, paused=0, paused_left=0, start_at=?, end_at=?, run_minutes=?, updated_at=? WHERE id=1')
        .bind(lvl, now, now + mins * 60000, mins, now));
      await db.batch(stmts);
      return json({ ok: true, config: publicConfig(await getEvent(db), Date.now()) });
    }
    case 'pause':
      if (ev.paused || !ev.end_at || ev.end_at <= now) return json({ ok: false, error: 'Nothing is running to pause.' });
      s = db.prepare('UPDATE event_3l SET paused=1, paused_left=?, end_at=NULL, updated_at=? WHERE id=1').bind(ev.end_at - now, now);
      break;
    case 'resume':
      if (!ev.paused) return json({ ok: false, error: 'The clock is not paused.' });
      s = db.prepare('UPDATE event_3l SET paused=0, end_at=?, paused_left=0, updated_at=? WHERE id=1').bind(now + ev.paused_left, now);
      break;
    case 'add': {
      const delta = Math.max(-600, Math.min(600, int(body.minutes))) * 60000;
      if (ev.paused) s = db.prepare('UPDATE event_3l SET paused_left=?, updated_at=? WHERE id=1').bind(Math.max(0, ev.paused_left + delta), now);
      else if (ev.end_at && ev.end_at > now) s = db.prepare('UPDATE event_3l SET end_at=?, updated_at=? WHERE id=1').bind(Math.max(now, ev.end_at + delta), now);
      else return json({ ok: false, error: 'Start a level first.' });
      break;
    }
    case 'end':
      if (!ev.open || !running) return json({ ok: false, error: 'No level is running.' });
      s = db.prepare('UPDATE event_3l SET paused=0, paused_left=0, end_at=?, updated_at=? WHERE id=1').bind(now, now);
      break;
    case 'reset':
      s = db.prepare('UPDATE event_3l SET round=round+1, level=0, open=0, paused=0, paused_left=0, start_at=NULL, end_at=NULL, updated_at=? WHERE id=1').bind(now);
      break;
    case 'remove':
      await db.batch([
        db.prepare('DELETE FROM teams_3l WHERE round=? AND team_key=?').bind(ev.round, str(body.teamKey, 300)),
        db.prepare('DELETE FROM levels_3l WHERE round=? AND team_key=?').bind(ev.round, str(body.teamKey, 300))
      ]);
      return json({ ok: true });
    default:
      return json({ ok: false, error: 'Unknown action' }, 400);
  }
  await s.run();
  return json({ ok: true, config: publicConfig(await getEvent(db), Date.now()) });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const path = url.pathname.replace(/\/+$/, '') || '/';
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });

    if (path === '/host') {
      return new Response(HOST_PAGE, { headers: { 'Content-Type': 'text/html;charset=utf-8', 'Cache-Control': 'no-store' } });
    }
    if (!env.DB) return json({ ok: false, error: 'No D1 database bound. Add a D1 binding named DB in the Worker settings.' }, 500);
    const db = env.DB;
    await ensureSchema(db);
    const now = Date.now();

    try {
      if (path.startsWith('/api/host/')) {
        if (!env.HOST_PIN) return json({ ok: false, error: 'HOST_PIN is not set. Add it under Worker → Settings → Variables and Secrets.' }, 500);
        if (req.headers.get('X-Host-Pin') !== String(env.HOST_PIN)) return json({ ok: false, error: 'Wrong host PIN.' }, 401);
        if (path === '/api/host/board') {
          const ev = await getEvent(db);
          const round = url.searchParams.get('round') ? int(url.searchParams.get('round')) : ev.round;
          const t = await db.prepare('SELECT * FROM teams_3l WHERE round=? ORDER BY first_seen').bind(round).all();
          const l = await db.prepare('SELECT * FROM levels_3l WHERE round=?').bind(round).all();
          return json({ ok: true, config: publicConfig(ev, now), round, teams: t.results, levels: l.results });
        }
        if (path === '/api/host/action' && req.method === 'POST') {
          return handleHostAction(db, await req.json().catch(() => ({})), now);
        }
        return json({ ok: false, error: 'Not found' }, 404);
      }

      if (req.method === 'GET') {
        const ev = await getEvent(db);
        const cfg = publicConfig(ev, now);
        const tk = url.searchParams.get('team');
        if (tk) {
          const row = await db.prepare('SELECT allowed_level FROM teams_3l WHERE round=? AND team_key=?').bind(ev.round, str(tk, 300).toLowerCase()).first();
          cfg.me = row ? { known: true, allowed: row.allowed_level | 0 } : { known: false, allowed: 0 };
        }
        return json(cfg);
      }
      if (req.method === 'POST' && path === '/') {
        let d; try { d = JSON.parse(await req.text()); } catch (e) { return json({ ok: false, error: 'bad json' }, 400); }
        return handlePlayerPost(db, d || {}, now);
      }
      return json({ ok: false, error: 'Not found' }, 404);
    } catch (err) {
      return json({ ok: false, error: String(err && err.message || err) }, 500);
    }
  }
};
